import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdint>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int THREADS = 256;

__global__ void cute_matvec_kernel(
    const float* A,
    const float* B,
    float* C,
    int M,
    int K)
{
    constexpr int WARPS_PER_BLOCK = THREADS / 32;
    constexpr int TILE_K = 2048;
    __shared__ __align__(16) float smem_B[TILE_K];

    const int tid = static_cast<int>(threadIdx.x);
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int row = static_cast<int>(blockIdx.x) * WARPS_PER_BLOCK + warp;
    const bool active_row = row < M;
    const bool vectorized =
        ((K & 3) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(A) & 15u) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(B) & 15u) == 0);

    float accum = 0.0f;

    for (int tile_base = 0; tile_base < K; tile_base += TILE_K) {
        const int tile_end = min(tile_base + TILE_K, K);
        const int tile_size = tile_end - tile_base;

        if (vectorized && ((tile_size & 3) == 0)) {
            const int vec_count = tile_size >> 2;
            const float4* b_vec = reinterpret_cast<const float4*>(B + tile_base);
            float4* smem_b_vec = reinterpret_cast<float4*>(smem_B);
            for (int i = tid; i < vec_count; i += THREADS) {
                smem_b_vec[i] = b_vec[i];
            }
        } else {
            for (int k = tid; k < tile_size; k += THREADS) {
                smem_B[k] = B[tile_base + k];
            }
        }
        __syncthreads();

        if (active_row) {
            const float* row_a = A + static_cast<std::size_t>(row) * K;
            if (vectorized && ((tile_size & 3) == 0)) {
                const int vec_count = tile_size >> 2;
                const float4* a_vec = reinterpret_cast<const float4*>(row_a + tile_base);
                const float4* b_vec = reinterpret_cast<const float4*>(smem_B);
                for (int i = lane; i < vec_count; i += 32) {
                    const float4 av = a_vec[i];
                    const float4 bv = b_vec[i];
                    accum = fmaf(av.x, bv.x, accum);
                    accum = fmaf(av.y, bv.y, accum);
                    accum = fmaf(av.z, bv.z, accum);
                    accum = fmaf(av.w, bv.w, accum);
                }
            } else {
                for (int k = lane; k < tile_size; k += 32) {
                    accum = fmaf(row_a[tile_base + k], smem_B[k], accum);
                }
            }
        }
        __syncthreads();
    }

    if (active_row) {
        for (int offset = 16; offset > 0; offset >>= 1) {
            accum += __shfl_down_sync(0xFFFFFFFFu, accum, offset);
        }
        if (lane == 0) {
            C[row] = accum;
        }
    }
}


torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must have shape (M, K)");
    TORCH_CHECK(B.dim() == 2, "B must have shape (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int M = static_cast<int>(A.size(0));
    const int K = static_cast<int>(A.size(1));

    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");

    auto C = torch::empty({M, 1}, A.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matvec_kernel<<<
        dim3((M + THREADS / 32 - 1) / (THREADS / 32)),
        dim3(THREADS),
        2048 * sizeof(float),
        stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix-vector kernel launch failed");

    return C;
}
"""


cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)

